insert into categories (game_id, name) values
  ('truth-or-lie', 'ไหวพริบ')
on conflict (game_id, name) do nothing;

with cat as (
  select id, name from categories where game_id = 'truth-or-lie'
)
insert into questions (game_id, category_id, text, answer, explain)
select 'truth-or-lie', cat.id, v.text, v.answer, v.explain
from (values
    ('ไหวพริบ', 'เทน้ำเปล่าใส่แก้วเปล่า แสดงว่าในแก้วไม่มีน้ำเปล่า', false, 'ผิด! พอเทน้ำลงไปแล้ว แก้วนั้นก็มีน้ำอยู่ข้างในทันที ไม่ใช่แก้วเปล่าอีกต่อไป'),
    ('ไหวพริบ', 'เทน้ำแข็งลงในแก้วเปล่า แสดงว่าตอนนี้แก้วนั้นไม่มีอะไรอยู่ข้างในเลย', false, 'ผิด! มีน้ำแข็งอยู่ในแก้วแล้ว แก้วจึงไม่ได้ว่างเปล่าอีกต่อไป'),
    ('ไหวพริบ', 'พูดคำว่า ''เงียบ'' ออกมาดังๆ แสดงว่าขณะนั้นไม่เงียบแล้ว', true, 'ถูก! การพูดออกเสียงคำว่า ''เงียบ'' คือการทำเสียง ซึ่งขัดแย้งกับความเงียบในตัวมันเอง'),
    ('ไหวพริบ', 'ตู้เย็นเปิดประตูค้างไว้ในห้องปิด จะทำให้อุณหภูมิห้องเย็นลงเรื่อยๆ ไม่มีที่สิ้นสุด', false, 'ผิด! ตู้เย็นระบายความร้อนออกทางด้านหลัง มอเตอร์ที่ทำงานหนักขึ้นจะปล่อยความร้อนออกมามากกว่าความเย็นที่ดูดเข้าไป สุดท้ายห้องจะอุ่นขึ้นเล็กน้อยแทน'),
    ('ไหวพริบ', '1 บวก 1 มีค่าเท่ากับ 2 เสมอไม่ว่าในระบบเลขฐานใดก็ตาม', false, 'ผิด! ในระบบเลขฐานสอง (ไบนารี) ซึ่งคอมพิวเตอร์ใช้ 1+1 เขียนแทนด้วย 10 ไม่ใช่ 2'),
    ('ไหวพริบ', 'ถ้าวิ่งไปชนกำแพงแรงๆ กำแพงจะไม่ได้รับแรงกระแทกใดๆ เพราะกำแพงอยู่นิ่งไม่ขยับ', false, 'ผิด! ตามกฎข้อที่ 3 ของนิวตัน (แรงกิริยา-ปฏิกิริยา) กำแพงรับแรงเท่ากับแรงที่ถูกกระแทกจริง แม้จะไม่ขยับตำแหน่งก็ตาม'),
    ('ไหวพริบ', 'เหรียญที่โยนขึ้นแล้วตกลงพื้น มีโอกาสออกหัวหรือก้อยเท่ากันเป๊ะ 50-50 เสมอ', false, 'ผิด! งานวิจัยทางสถิติพบว่าเหรียญมีแนวโน้มออกด้านเดียวกับด้านที่หงายอยู่ตอนเริ่มโยนมากกว่าเล็กน้อย ไม่ใช่ 50-50 เป๊ะ'),
    ('ไหวพริบ', 'ถ้าปิดตาแล้วพยายามเดินตรงไปเรื่อยๆ โดยไม่มีสิ่งกีดขวาง คนส่วนใหญ่จะเดินเป็นเส้นตรงได้จริง', false, 'ผิด! การทดลองพบว่าคนส่วนใหญ่มักเดินวนเป็นวงกลมโดยไม่รู้ตัว เมื่อไม่มีจุดอ้างอิงทางสายตาให้เดินตรง'),
    ('ไหวพริบ', 'คำว่า ''คำถาม'' ในประโยคคำถามข้อนี้ ปรากฏอยู่ในตัวประโยคคำถามข้อนี้จริง', true, 'ถูก! เป็นการเล่นคำเชิงตรรกะที่อ้างอิงถึงตัวมันเอง (self-reference) ลองอ่านประโยคซ้ำอีกทีจะเห็นคำว่า ''คำถาม'' อยู่จริง'),
    ('ไหวพริบ', 'กระจกเงาสะท้อนภาพกลับด้านซ้าย-ขวา แต่ไม่กลับด้านบน-ล่าง', true, 'ถูก! แต่จริงๆ แล้วกระจกสะท้อนกลับด้านหน้า-หลัง (แกนที่ตั้งฉากกับกระจก) ไม่ใช่ซ้าย-ขวาโดยตรง ที่ดูเหมือนกลับซ้ายขวาเป็นเพราะสมองตีความภาพสะท้อนของร่างกายเราเอง'),
    ('ไหวพริบ', 'คนที่ตอบว่า ''ไม่รู้'' ต่อคำถามหนึ่งๆ แสดงว่าอย่างน้อยเขารู้อยู่แล้วว่าตัวเองไม่รู้คำตอบ', true, 'ถูก! เป็นการเล่นตรรกะเรื่องการรู้ตัวว่าไม่รู้ (meta-knowledge) การบอกว่า ''ไม่รู้'' ได้ต้องอาศัยการประเมินตัวเองก่อนว่าไม่มีคำตอบนั้นอยู่'),
    ('ไหวพริบ', 'ถ้าอยู่ในห้องมืดสนิทไม่มีแสงเข้าเลย การลืมตาหรือหลับตาจะมองเห็นแตกต่างกัน', false, 'ผิด! ในความมืดสนิทแบบไม่มีแสงเลย ลืมตาหรือหลับตาก็มองไม่เห็นอะไรเหมือนกันทั้งคู่ เพราะดวงตาต้องอาศัยแสงสะท้อนถึงจะมองเห็นได้'),
    ('ไหวพริบ', 'ประโยคที่ว่า ''ประโยคนี้เป็นเท็จ'' สามารถตอบได้ชัดเจนว่าเป็นจริงหรือเท็จ', false, 'ผิด! นี่คือปฏิทรรศน์คนพูดเท็จ (Liar''s Paradox) ถ้าประโยคเป็นจริง แสดงว่ามันเป็นเท็จตามที่มันบอก แต่ถ้าเป็นเท็จ มันก็กลับเป็นจริง จึงระบุค่าความจริงที่แน่นอนไม่ได้เลย'),
    ('ไหวพริบ', 'ถ้าเห็นเงาตัวเองยาวมากตอนพระอาทิตย์เพิ่งขึ้นหรือใกล้ตก แสดงว่าดวงอาทิตย์อยู่ใกล้โลกมากขึ้นในช่วงเวลานั้น', false, 'ผิด! ระยะห่างจากดวงอาทิตย์แทบไม่เปลี่ยนแปลงภายในหนึ่งวัน เงายาวเพราะมุมแสงตกกระทบเอียงต่ำในช่วงเช้า/เย็น ไม่เกี่ยวกับระยะห่างของดวงอาทิตย์เลย')
  ) as v(cat_name, text, answer, explain)
join cat on cat.name = v.cat_name
where not exists (
  select 1 from questions q2
  where q2.game_id = 'truth-or-lie' and q2.text = v.text
);